package com.prakash.gmcemp.route.model;import jakarta.persistence.*;@Entity @Table(name="route_master",uniqueConstraints=@UniqueConstraint(columnNames={"originPort","destinationPort"})) public class Route{@Id @GeneratedValue(strategy=GenerationType.IDENTITY)private Long id;private String originPort;private String destinationPort;private Double distanceKm;private String originCountry;private String destinationCountry;public Long getId(){return id;}public String getOriginPort(){return originPort;}public void setOriginPort(String v){originPort=v;}public String getDestinationPort(){return destinationPort;}public void setDestinationPort(String v){destinationPort=v;}public Double getDistanceKm(){return distanceKm;}public void setDistanceKm(Double v){distanceKm=v;}public String getOriginCountry(){return originCountry;}public void setOriginCountry(String v){originCountry=v;}public String getDestinationCountry(){return destinationCountry;}public void setDestinationCountry(String v){destinationCountry=v;}}